import type { ModelKey } from '../../translator-core/src/index';
import manifest from './model-manifest.json';

export type { ModelKey } from '../../translator-core/src/index';

export interface ModelAsset {
  path: string;
  bytes: number;
  sha256: string;
}

export interface ModelManifestEntry {
  key: ModelKey;
  id: string;
  revision: string;
  label: string;
  parameters: number;
  license: string;
  licenseUrl: string;
  files: ModelAsset[];
  totalBytes: number;
}

/** Immutable commits and hashes are generated by scripts/verify-models.py. */
export const MODEL_MANIFEST = manifest as Record<ModelKey, ModelManifestEntry>;
export const MODEL_CACHE = 'local-translator-models-v1';

export function modelAssetUrl(model: ModelKey, path: string): string {
  const entry = MODEL_MANIFEST[model];
  if (!entry.files.some((asset) => asset.path === path)) {
    throw new Error(`Unlisted model asset: ${path}`);
  }
  return `https://huggingface.co/${entry.id}/resolve/${entry.revision}/${path}`;
}
